struct {
		Role      string     `json:"role"`
		Content   string     `json:"content"`
		ToolCalls []ToolCall `json:"tool_calls,omitempty"`
	}

{
    autoPrOnApprove: boolean;
    defaultBranch: string | null;
    integrationBranch?: string;
    releaseBranch?: string;
    autoMergeIntegrationPr?: boolean;
    /** Create integration branch on remote from default tip if missing */
    ensureIntegrationBranch?: boolean;
  }

{
    savings: number;
    baseline_tokens: number;
    baseline_full_context_tokens: number;
    actual_tokens_sent: number;
    total_input_tokens: number;
    total_output_tokens: number;
    // Grok uplift (AST Savings card): complete fields for cost + historical projection.
    // Addresses review gap (incomplete TS types). estimated_cost_usd uses env rates or defaults
    // applied to actual burn; historical_burn is the by_worker agg shape (powers the historical table).
    // See backend handleSnapshot "8. Token telemetry savings" + lightweight size:0 aggs.
    estimated_cost_usd?: number;
    historical_burn?: Array<{
      worker_name: string;
      input_tokens: number;
      output_tokens: number;
      role: string;
    }>;
    // Recommendation 1: local mesh / hybrid AST Savings (populated server-side when Elastro savings==0)
    // Derived data-driven from Telemetry Bridge (flume_worker_tokens_total + routing decisions + node loads).
    // local_mesh_estimated_savings: estimated tokens avoided in pure local mesh via intelligent routing + structural (LogLoom-path) awareness.
    // mesh_efficiency_note: explains the hybrid model and derivation factors (observable via LogAgentReasoning on backend).
    local_mesh_estimated_savings?: number;
    mesh_efficiency_note?: string;
  } (optional)

Array<{
    '@timestamp': string;
    message: string;
    agent_roles: string;
    worker_name: string;
    secret_path: string;
    keys_retrieved: string[];
  }>

